// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.synthimport timber.log.Timberimport com.roshan.persona.voice.tts.VoicePersonaimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport kotlin.math.PIimport kotlin.math.sin/** * NOUS — Audio Synthesizer (§14 Audio Synthesizer / Sound Effects). * * Plays sound effects and generates tones for non-verbal UI feedback. * Distinct from [com.roshan.persona.voice.tts.EmotionalTtsEngine] which * handles *speech*; this class handles *cues* — short audio signals that * communicate state faster than a spoken sentence. * * ## Two output modes (§14) * *  1. **Pre-recorded effects** — [playSoundEffect] loads a .wav from *     assets and plays it via [AudioOutput]. Higher quality (layered *     instruments, fades), used for ARC_REACTOR_HUM, BOOT_STARTUP, etc. * *  2. **Programmatic tones** — [generateTone] synthesizes a sine/square/ *     triangle/sawtooth wave on the fly. Zero asset storage, infinite *     flexibility. Used for short UI cues (button click, error beep). * * ## Why both? (§14 + §25 Q8) * * Pre-recorded effects sound better but require asset storage (the 5 .wav * files total ~500 KB). Tones are free but sound "computery". The user * gets the best of both: rich effects for important moments (boot, success) * + lightweight tones for frequent interactions (clicks, beeps). * * All output is gated by [AudioSynthesizerConfig.enabled] (per §25 Q8, * user can disable all sound effects in Settings). The arc reactor hum has * its own gate ([AudioSynthesizerConfig.arcReactorHumEnabled]) because * some users find continuous ambient hum unsettling. * * ## Testability * * [AudioOutput] is an interface — tests inject [RecordingAudioOutput] which * captures the PCM samples without playing them. [generateToneSamples] is * a pure function (internal visibility) so tests can verify the waveform * math directly. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§14 Audio Synthesizer (Sound Effects)</a> */class AudioSynthesizer(    private val audioOutput: AudioOutput,    private val assetLoader: AssetLoader,    private val config: AudioSynthesizerConfig = AudioSynthesizerConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Play a pre-recorded [SoundEffect] from assets.     *     * @param effect  which effect to play.     * @param volume  override the effect's default volume (0.0–1.0), or null     *                to use [SoundEffect.defaultVolume].     */    suspend fun playSoundEffect(effect: SoundEffect, volume: Float? = null) = withContext(dispatcher) {        if (!config.enabled) {            Timber.tag(TAG).d("Sound effects disabled — skipping ${effect.name}.")            return@withContext        }        if (effect == SoundEffect.ARC_REACTOR_HUM && !config.arcReactorHumEnabled) {            Timber.tag(TAG).d("Arc reactor hum disabled — skipping.")            return@withContext        }        val effectiveVolume = (volume ?: effect.defaultVolume) * config.masterVolume        val pcm = runCatching { assetLoader.loadPcm(effect.filePath) }            .onFailure { Timber.tag(TAG).w("Failed to load ${effect.filePath}", it) }            .getOrNull() ?: return@withContext        audioOutput.playPcm(pcm, config.sampleRate, effectiveVolume)    }    /**     * Play the per-persona notification chime (§14 NOTIFICATION_CHIME).     *     * Each persona has a distinct chime — see [PersonaChimeMapping].     */    suspend fun playPersonaChime(persona: VoicePersona) = withContext(dispatcher) {        if (!config.enabled) return@withContext        val chime = PersonaChimeMapping.chimeFor(persona)        generateTone(chime)    }    /**     * Generate and play a programmatic tone.     *     * @param spec tone specification (frequency, duration, volume, waveform).     */    suspend fun generateTone(spec: ToneSpec) = withContext(dispatcher) {        if (!config.enabled) return@withContext        val effectiveVolume = spec.volume * config.masterVolume        val pcm = generateToneSamples(spec, config.sampleRate)        audioOutput.playPcm(pcm, config.sampleRate, effectiveVolume)    }    // ──────────────────────────────────────────────────────────────────────    /**     * Generate PCM samples for a tone.     *     * Pure function — internal visibility so tests can verify the waveform     * math (sine vs square vs triangle vs sawtooth) without playing audio.     *     * @param spec        tone specification.     * @param sampleRate  output sample rate (Hz).     * @return 16-bit PCM samples, mono.     */    internal fun generateToneSamples(spec: ToneSpec, sampleRate: Int): ShortArray {        val numSamples = (sampleRate * spec.durationMs / 1000).toInt()        val out = ShortArray(numSamples)        val amplitude = spec.volume * Short.MAX_VALUE        for (i in 0 until numSamples) {            val t = i.toDouble() / sampleRate            val phase = 2 * PI * spec.frequencyHz * t            val sample = when (spec.waveform) {                Waveform.SINE -> sin(phase)                Waveform.SQUARE -> if (sin(phase) >= 0) 1.0 else -1.0                Waveform.TRIANGLE -> {                    // Triangle: 2/π × arcsin(sin(phase))                    kotlin.math.asin(sin(phase)) * (2 / PI)                }                Waveform.SAWTOOTH -> {                    // Sawtooth: 2 × (t × f - floor(0.5 + t × f))                    val normalized = (spec.frequencyHz * t) % 1.0                    2 * normalized - 1                }            }            out[i] = (amplitude * sample).toInt()                .coerceIn(Short.MIN_VALUE.toInt(), Short.MAX_VALUE.toInt())                .toShort()        }        return out    }    /**     * Mix two PCM sample arrays (for layering tones).     *     * Used by the caller to combine, e.g., an arc reactor hum with a chime.     * Both inputs must have the same length; the output is the average of     * the two (prevents clipping when both are at full volume).     */    internal fun mixPcm(a: ShortArray, b: ShortArray): ShortArray {        require(a.size == b.size) { "PCM arrays must have same length: ${a.size} vs ${b.size}" }        val out = ShortArray(a.size)        for (i in a.indices) {            val mixed = (a[i].toInt() + b[i].toInt()) / 2            out[i] = mixed.coerceIn(Short.MIN_VALUE.toInt(), Short.MAX_VALUE.toInt()).toShort()        }        return out    }    private companion object {        private const val TAG = "AudioSynthesizer"    }}// ──────────────────────────────────────────────────────────────────────────/** * Audio output sink — abstracted over [android.media.AudioTrack]. * * Tests inject [RecordingAudioOutput] which captures samples without playing * them. Real impl ([AndroidAudioOutput]) wraps AudioTrack with STREAM_MUSIC * and writes PCM samples. */interface AudioOutput {    /** Play a buffer of 16-bit PCM mono samples at [sampleRate] Hz. */    suspend fun playPcm(samples: ShortArray, sampleRate: Int, volume: Float)    /** Release the underlying AudioTrack. */    fun release()}/** * Asset loader — abstracted over [android.content.res.AssetManager]. * * Loads pre-recorded .wav files as 16-bit PCM ShortArrays. Tests inject a * fake that returns canned samples. */fun interface AssetLoader {    /** Load a .wav file from assets and return its PCM samples. */    suspend fun loadPcm(filePath: String): ShortArray}// ──────────────────────────────────────────────────────────────────────────/** * Test-only [AudioOutput] that records every played sample buffer. * * Useful for verifying that the synthesizer produced the expected waveform * without actually playing audio (which would require a real device). */class RecordingAudioOutput : AudioOutput {    val recorded = mutableListOf<Pair<ShortArray, Float>>()    override suspend fun playPcm(samples: ShortArray, sampleRate: Int, volume: Float) {        recorded += samples.copyOf() to volume    }    override fun release() = Unit    /** Reset the recorded buffers (for between sub-tests). */    fun reset() {        recorded.clear()    }}

